DO $$ DECLARE b text; f record; BEGIN FOR f IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('rpc_regulatory_review_decide','rpc_regulatory_dossier_publish') LOOP b:=pg_get_functiondef(f.oid); b:=regexp_replace(b,'BEGIN','BEGIN IF NOT platform_private.product_dossier_row_read(p_dossier_id) THEN RAISE EXCEPTION ''REGULATORY_FORBIDDEN'' USING ERRCODE=''42501''; END IF;'); EXECUTE b; END LOOP; END $$;